@dataclass(eq=False, repr=False)
class TriggerReclusterRequest(betterproto.Message):
    """
    TriggerReclusterRequest names the RAG partitions to recluster. At least one
     partition id is required, and at most a small server-defined maximum per
     request (RECLUSTER_MAX_PARTITIONS_PER_REQUEST) -- reclusters are serialized and
     each blocks all writes for its full run, so oversized batches are rejected
     rather than silently deferring most of the work. Split large reclustering into
     smaller batches, ideally during a maintenance window.
    """

    partition_ids: List[str] = betterproto.string_field(1)


@dataclass(eq=False, repr=False)
class ReclusterPartitionStatus(betterproto.Message):
    """
    ReclusterPartitionStatus is the per-partition scheduling outcome. The recluster
     itself runs in the background; this only reports whether it was accepted for
     scheduling. For progress, the project-metadata importerOrchestration status slot
     carries the running/completed/failed of a single job at a time -- with several
     partitions their writes overwrite one another, so it is NOT a per-partition
     ledger. The authoritative per-partition outcome is the rags node itself:
     needs_reclustering (cleared on success) and last_reclustered_at; poll those per
     partition when reclustering more than one.
    """

    rag_partition_id: str = betterproto.string_field(1)
    accepted: bool = betterproto.bool_field(2)
    error_message: Optional[str] = betterproto.string_field(3, optional=True)


@dataclass(eq=False, repr=False)
class TriggerReclusterResponse(betterproto.Message):
    """
    TriggerReclusterResponse returns one scheduling result per requested partition.
    """

    results: List["ReclusterPartitionStatus"] = betterproto.message_field(1)


